// The existing processed cue, ball, cushion and pocket recordings encoded as MP3.
// Keeping this small bank in one module avoids a network request per first-shot sound.
const clips = Object.freeze({
  "rs-ball-hard-01.wav": "",
  "rs-ball-hard-02.wav": "",
  "rs-ball-hard-03.wav": "",
  "rs-ball-medium-01.wav": "",
  "rs-ball-medium-02.wav": "",
  "rs-ball-medium-03.wav": "",
  "rs-ball-medium-04.wav": "",
  "rs-ball-soft-01.wav": "",
  "rs-ball-soft-02.wav": "",
  "rs-ball-soft-03.wav": "",
  "rs-cue-hard-01.wav": "",
  "rs-cue-medium-01.wav": "",
  "rs-cue-soft-01.wav": "",
  "rs-cue-very-hard-01.wav": "",
  "rs-cue-very-soft-01.wav": "",
  "rs-cushion-hard-01.wav": "",
  "rs-cushion-medium-01.wav": "",
  "rs-cushion-soft-01.wav": "",
  "rs-pocket-drop-01.wav": "",
  "rs-pocket-hard-01.wav": "",
  "rs-pocket-soft-01.wav": ""
});

const prefix = new URL("./resources/audio/impact-processed/", import.meta.url).href;

export function fetchEntryImpactAudio(source, options) {
  const clip = source.startsWith(prefix) && clips[source.slice(prefix.length)];
  if (!clip) return fetch(source, options);
  return Promise.resolve(new Response(Uint8Array.from(atob(clip), byte => byte.charCodeAt(0))));
}
